import { Component, EventEmitter, Input, Output } from '@angular/core';
import { SuperService } from '../../controllers/super.service';
import { BaseModel } from '../../models/base.model';

@Component({
    selector: 'app-record-form',
    imports: [],
    templateUrl: './record-form.component.html',
    styleUrl: './record-form.component.css'
})
export class RecordFormComponent<T=BaseModel> {
  @Input() record!:T&BaseModel&{id:number}
  @Output() onEditing= new EventEmitter()
  @Output() onSaved= new EventEmitter()
  @Output() onDeleted= new EventEmitter()

  edit=false
  isLoading=false
  isDeleting=false

  

  constructor(private controller: SuperService<T&BaseModel>){}

  ngOnInit(){
    this.checkIfIsEditing()
  }
  
  protected checkIfIsEditing(){
    if(!this.record.id){
      this.edit=true
    }
  }

  public async save(){
    this.isLoading=true
    const res= await this.controller.createOrUpdate(this.record)
    if(res){
      this.record.id=res.id
      await this.afterSaved()
      this.onSaved.emit()
    }
    this.edit=false
    this.isLoading=false
  }

  protected async afterSaved(){

  }

  protected afterSavedLocal(){
    
  }

  public async delete(){
    this.isDeleting=true
    if(!this.record.id){
      this.onDeleted.emit()
      return
    }
    const res= await this.controller.switch(this.record,undefined,false)
    if(res){
      this.onDeleted.emit()
    }
    this.isDeleting=false
  }
}